// ReturnShield - Ask Agent (companion workflow, spec sections 17 + 24)
// Accepts either: { question, context: <the full Final JSON Builder response> }
// or:             { question, run_id: "rs_..." }  (looked up from the "returnshield_runs" Data Table)

const body = $input.first().json.body !== undefined ? $input.first().json.body : $input.first().json;

const question = body && typeof body.question === 'string' ? body.question.trim() : '';
const context = body && typeof body.context === 'object' && body.context !== null ? body.context : null;
const run_id = body && typeof body.run_id === 'string' ? body.run_id.trim() : null;

const valid = !!question && (!!context || !!run_id);

let error = null;
if (!question) error = 'Missing "question" (string).';
else if (!context && !run_id) error = 'Provide either "context" (the full analysis JSON from a ReturnShield run) or "run_id" (to look one up).';

return [{
  json: {
    valid,
    error,
    question,
    context,
    run_id
  }
}];

const j = $json;
return [{
  json: {
    product: 'ReturnShield AI',
    error: true,
    message: j.error || j.lookup_error,
    expected_format: {
      question: 'string (required)',
      context: '(one of context/run_id required) the full JSON response from a ReturnShield analysis run',
      run_id: '(one of context/run_id required) run id from a previous analysis, if Store Analysis Snapshot / Data Tables are set up'
    },
    generated_at: new Date().toISOString()
  }
}];

// Runs only when the request supplied a run_id instead of inline context.
// Reads whatever "Fetch Context By Run ID" (Data Table get) produced - which
// may be zero/one row, or an error item if the Data Table isn't configured yet.
const requestItem = $('Prepare & Validate Ask Request').first().json;

let fetched = null;
try {
  const items = $input.all();
  const row = items.find(it => it.json && it.json.snapshot_json);
  if (row) fetched = JSON.parse(row.json.snapshot_json);
} catch (e) {
  fetched = null;
}

if (!fetched) {
  return [{
    json: {
      valid: false,
      question: requestItem.question,
      context: null,
      lookup_error: 'Could not find a stored analysis for run_id "' + requestItem.run_id + '". Make sure the "returnshield_runs" Data Table exists and that run actually completed with Store Analysis Snapshot enabled, or pass "context" inline instead.'
    }
  }];
}

return [{ json: { valid: true, question: requestItem.question, context: fetched } }];

// Single canonical node that both the "context provided inline" branch and
// the "context fetched by run_id" branch feed into. Every Code Tool below
// reads its data from $('Context Ready').first().json.context so there's
// exactly one place tools need to know about, regardless of how the caller
// supplied the analysis.
const j = $json;
return [{ json: { question: j.question, context: j.context } }];

// Tool contract: input is the string variable `query`. Must return a string.
// No $input/$helpers here - but $('NodeName') references to earlier nodes in
// this same workflow execution DO work, which is how every tool below reads
// the shared analysis context without re-fetching or re-computing anything.
const ctx = $('Context Ready').first().json.context;

let dimension = null, value = null;
try {
  const parsed = JSON.parse(query);
  dimension = parsed.dimension; value = parsed.value;
} catch (e) {
  const parts = String(query).split(':');
  if (parts.length >= 2) { dimension = parts[0].trim().toLowerCase(); value = parts.slice(1).join(':').trim(); }
  else { value = String(query).trim(); }
}

const DIMENSIONS = ['sku', 'courier', 'pincode', 'zone', 'category', 'payment_method'];
const segments = ctx.segments || {};
let candidates = [];

if (dimension && DIMENSIONS.includes(dimension)) {
  candidates = (segments[dimension] || []).filter(s => String(s.value).toLowerCase() === String(value).toLowerCase());
} else {
  DIMENSIONS.forEach(d => {
    (segments[d] || []).forEach(s => {
      if (String(s.value).toLowerCase() === String(value).toLowerCase()) candidates.push(s);
    });
  });
}

if (!candidates.length) {
  return JSON.stringify({
    found: false,
    message: 'No segment found matching "' + query + '". Valid dimensions are sku, courier, pincode, zone, category, payment_method. Pass as "dimension:value", e.g. "courier:Xpress Logistics".'
  });
}

const totalAffected = (ctx.metrics && ctx.metrics.affected_order_value_inr) || 0;

const result = candidates.map(s => Object.assign({}, s, {
  share_of_total_affected_value_pct: totalAffected > 0 ? Math.round((s.order_value_lost_inr / totalAffected) * 1000) / 10 : null
}));

return JSON.stringify({ found: true, segments: result });

const ctx = $('Context Ready').first().json.context;
const ra = ctx.reason_analysis || { return_categories: [], rto_categories: [], unclassified_count: 0 };

const q = String(query || '').trim().toLowerCase();
let out;
if (q.startsWith('return')) out = { return_categories: ra.return_categories };
else if (q.startsWith('rto')) out = { rto_categories: ra.rto_categories };
else out = ra;

return JSON.stringify(out);

const ctx = $('Context Ready').first().json.context;
const topProblems = ctx.top_problems || [];

let n = parseInt(query, 10);
if (!Number.isFinite(n) || n <= 0) n = topProblems.length;

return JSON.stringify({ top_problems: topProblems.slice(0, n) });

const ctx = $('Context Ready').first().json.context;
const recs = ctx.recommendations || [];

const q = String(query || '').trim().toUpperCase();
const validTiers = ['P0', 'P1', 'P2', 'P3'];
let out = recs;
if (validTiers.includes(q)) out = recs.filter(r => r.priority === q);

return JSON.stringify({ recommendations: out });

const ctx = $('Context Ready').first().json.context;
const trends = ctx.trends || [];

if (!trends.length || !trends[0] || trends[0].available === false) {
  return JSON.stringify({
    available: false,
    message: (trends[0] && trends[0].note) || 'No previous run is available for comparison for this analysis.'
  });
}

return JSON.stringify(trends[0]);

const ctx = $('Context Ready').first().json.context;
const hypotheses = ctx.hypotheses || [];

const q = String(query || '').trim().toLowerCase();
let out = hypotheses;
if (q) {
  out = hypotheses.filter(h =>
    (h.segment_value && String(h.segment_value).toLowerCase().includes(q)) ||
    (h.source_problem && String(h.source_problem).toLowerCase().includes(q))
  );
  if (!out.length) out = hypotheses; // fall back to everything rather than a dead end
}

return JSON.stringify({ hypotheses: out });

const rawAgentItem = $input.first().json;
const agentFailed = !!rawAgentItem.error;
const agentOutput = rawAgentItem.output || rawAgentItem;
const requestItem = $('Context Ready').first().json;

const response = {
  product: 'ReturnShield AI - Ask',
  question: requestItem.question,
  answer: agentFailed
    ? 'The assistant could not complete this request after retries. Please try again, or ask a simpler, more specific question.'
    : (agentOutput.answer || 'No answer was produced.'),
  confidence: agentFailed ? null : (agentOutput.confidence != null ? agentOutput.confidence : null),
  caveats: agentFailed ? [] : (agentOutput.caveats || []),
  tools_used: agentFailed ? [] : (agentOutput.tools_used || []),
  status: agentFailed ? 'failed' : 'success',
  generated_at: new Date().toISOString()
};

return [{ json: response }];

// Inbound Webhook Authentication Gate
const headers = $input.first().json.headers || {};
const authHeader = String(headers['authorization'] || headers['Authorization'] || '');
const secretHeader = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '');
const incomingSecret = secretHeader || (authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '');
const EXPECTED_SECRET = ($env && $env.N8N_WEBHOOK_SECRET) ? $env.N8N_WEBHOOK_SECRET : '';
const authorized = !EXPECTED_SECRET || (incomingSecret === EXPECTED_SECRET);

return [{
  json: {
    ...$input.first().json,
    _auth: {
      authorized,
      error: authorized ? null : 'Unauthorized: Missing or invalid X-Webhook-Secret header.'
    }
  }
}];

